import React from "react";
import { fmt, theme } from "../data";
import {
  Card,
  Metric,
  PageTitle,
  SliderInput,
  Table,
} from "../components/SharedComponents";

/*
  Historical reference values (from Method 1 raw data):
  - Avg annual supply: 1,286 approvals/year
  - Avg annual demand: 3,018 people/year
  - Avg annual gap: 1,733 units/year
  - Historical pop-growth-to-migration ratio (excl 2017-18): 1.47
    i.e. for every 1 migrant, population grows by ~1.47 additional via natural growth
  - Method 5 AAGR for house prices: 11.0%
  - Method 4 regression: population is the strongest price driver
*/

// Historical averages derived from the dataset
const AVG_SUPPLY = 1286;
const AVG_DEMAND = 3018;
const BASE_PRICE = 1280000; // 2024-25 actual

// Average ratio: popGrowth / migration across years where popGrowth > 0
// (2018-19 to 2024-25, excluding 2021-22 which had negative pop growth)
// Values: 1292/1524=0.85, 1072/1845=0.58, 511/3742=0.14, 2135/1436=1.49, 2662/1102=2.42, 2707/1000=2.71
// Mean of all 6 positive ratios = 1.36
const POP_GROWTH_RATIO = 1.36;

export default function SupplyPlanner({
  migInput,
  setMigInput,
  approvals,
  setApprovals,
  targetGrowth,
  setTargetGrowth,
}) {
  // Demand = migration + estimated population growth (using historical avg ratio)
  const estPopGrowth = Math.round(migInput * POP_GROWTH_RATIO);
  const demandPressure = migInput + estPopGrowth;

  // Required supply = enough approvals to meet demand
  const requiredSupply = demandPressure;
  const supplyGap = requiredSupply - approvals;

  // Price projection grounded in Method 5:
  // Base AAGR is 11%. When supply falls short, price grows faster;
  // when supply meets demand, price growth moderates toward the target.
  // Supply coverage ratio: approvals / demand. Historical avg ≈ 1,286/3,018 = 0.43
  const coverageRatio = demandPressure > 0 ? approvals / demandPressure : 1;
  const historicalCoverage = AVG_SUPPLY / AVG_DEMAND; // ~0.43

  // If coverage matches historical average → 11% growth (base AAGR)
  // Better coverage → lower growth; worse coverage → higher growth
  // Clamped between 3% and 18% to stay within reasonable bounds
  const adjustedGrowth = Math.min(
    18,
    Math.max(3, 11 * (historicalCoverage / Math.max(coverageRatio, 0.1))),
  );
  const priceNoAction = Math.round(BASE_PRICE * (1 + adjustedGrowth / 100));
  const priceTarget =
    BASE_PRICE + Math.round((BASE_PRICE * targetGrowth) / 100);

  // Moderate scenario: 30% more approvals
  const moderateApprovals = Math.round(approvals * 1.3);
  const moderateCoverage =
    demandPressure > 0 ? moderateApprovals / demandPressure : 1;
  const moderateGrowth = Math.min(
    18,
    Math.max(3, 11 * (historicalCoverage / Math.max(moderateCoverage, 0.1))),
  );
  const priceModerate = Math.round(BASE_PRICE * (1 + moderateGrowth / 100));

  return (
    <div className="screen fade-in">
      <PageTitle
        eyebrow="Interactive tool"
        title="Supply Planning Tool"
        subtitle="Estimate how many homes Wollongong needs to build."
      />

      <div className="tool-layout">
        <Card className="input-panel">
          <h3>Inputs</h3>

          <SliderInput
            label="Expected Annual Net Migration"
            value={migInput}
            onChange={setMigInput}
            min={500}
            max={5000}
            step={100}
            format={(v) => v.toLocaleString()}
          />

          <SliderInput
            label="Current Annual Approvals"
            value={approvals}
            onChange={setApprovals}
            min={500}
            max={3000}
            step={50}
            format={(v) => v.toLocaleString()}
          />

          <SliderInput
            label="Target Price Growth"
            value={targetGrowth}
            onChange={setTargetGrowth}
            min={0}
            max={15}
            step={0.5}
            format={(v) => `${v}%`}
          />

          <div className="callout blue">
            Historical avg supply is 1,286 approvals/year. Demand has averaged
            3,018/year. Population growth is estimated at 1.36× net migration
            based on the 2018–2025 average.
          </div>
        </Card>

        <div>
          <div className="metrics-grid two">
            <Metric
              label="Required Approvals"
              value={requiredSupply.toLocaleString()}
              sub="to match demand"
              tone={theme.blue}
            />

            <Metric
              label="Current Deficit"
              value={
                supplyGap > 0
                  ? `${supplyGap.toLocaleString()} short`
                  : "Surplus"
              }
              sub="homes/year"
              tone={supplyGap > 0 ? theme.red : theme.green}
            />

            <Metric
              label="Demand Pressure"
              value={demandPressure.toLocaleString()}
              sub="migration + est. pop growth"
              tone={theme.amber}
            />

            <Metric
              label="Price if No Action"
              value={fmt(priceNoAction)}
              sub={`~${adjustedGrowth.toFixed(1)}% growth`}
              tone={theme.red}
            />
          </div>

          <Card>
            <h3>Scenario comparison</h3>

            <Table
              headers={[
                "Scenario",
                "Approvals/yr",
                "Projected Price",
                "Growth",
              ]}
              rows={[
                [
                  "Do Nothing",
                  approvals.toLocaleString(),
                  fmt(priceNoAction),
                  `+${adjustedGrowth.toFixed(1)}%`,
                ],
                [
                  "Moderate (+30%)",
                  moderateApprovals.toLocaleString(),
                  fmt(priceModerate),
                  `+${moderateGrowth.toFixed(1)}%`,
                ],
                [
                  "Meet Target",
                  requiredSupply.toLocaleString(),
                  fmt(priceTarget),
                  `+${targetGrowth.toFixed(1)}%`,
                ],
              ]}
            />
          </Card>

          <Card className="callout blue" style={{ marginTop: 18 }}>
            <b>How this works:</b> Price growth is estimated using the
            historical base AAGR of 11%, adjusted by the ratio of supply
            coverage to the historical average (43%). When fewer homes are
            approved relative to demand, price growth accelerates; when more are
            approved, it moderates. This is a simplified illustrative model —
            actual price dynamics involve interest rates, policy changes, and
            broader economic conditions (see Method 6 limitations).
          </Card>
        </div>
      </div>
    </div>
  );
}
